"""Highest version in a list satisfying an npm-style range. See task.md."""

from __future__ import annotations

import re


class RangeError(ValueError):
    """Raised for malformed range expressions and malformed versions."""


_NUM = r"(?:0|[1-9][0-9]*)"
_PRE_ID = r"(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)"
_BUILD_ID = r"[0-9A-Za-z-]+"
_VERSION_RE = re.compile(
    rf"({_NUM})\.({_NUM})\.({_NUM})"
    rf"(?:-({_PRE_ID}(?:\.{_PRE_ID})*))?"
    rf"(?:\+({_BUILD_ID}(?:\.{_BUILD_ID})*))?"
)
_NUM_RE = re.compile(_NUM)
_OP_RE = re.compile(r"(>=|<=|>|<|=|\^|~)?(.*)", re.DOTALL)
_WILDCARDS = ("x", "X", "*")


def _parse_version(s: str):
    """Return (major, minor, patch, prerelease-tuple-or-None)."""
    m = _VERSION_RE.fullmatch(s)
    if not m:
        raise RangeError(f"malformed version: {s!r}")
    pre = tuple(m.group(4).split(".")) if m.group(4) is not None else None
    return (int(m.group(1)), int(m.group(2)), int(m.group(3)), pre)


def _key(v):
    major, minor, patch, pre = v
    if pre is None:
        return (major, minor, patch, 1, ())
    ids = tuple((0, int(i), "") if i.isdigit() else (1, 0, i) for i in pre)
    return (major, minor, patch, 0, ids)


def _parse_partial(s: str):
    """Return (parts, pre) where parts is a list of 0-3 ints (specified ones)."""
    if not s:
        raise RangeError("empty version in range")
    idx = min((i for i in (s.find("-"), s.find("+")) if i >= 0), default=-1)
    if idx >= 0:
        major, minor, patch, pre = _parse_version(s)
        return [major, minor, patch], pre
    segs = s.split(".")
    if len(segs) > 3:
        raise RangeError(f"malformed range version: {s!r}")
    parts = []
    wild = False
    for seg in segs:
        if seg in _WILDCARDS:
            wild = True
        elif wild or not _NUM_RE.fullmatch(seg):
            raise RangeError(f"malformed range version: {s!r}")
        else:
            parts.append(int(seg))
    return parts, None


def _complete(parts):
    return tuple(parts) + (0,) * (3 - len(parts))


def _bump(parts, idx):
    """Version tuple with component idx incremented and the rest zeroed."""
    full = list(_complete(parts))
    full[idx] += 1
    for i in range(idx + 1, 3):
        full[i] = 0
    return (full[0], full[1], full[2], None)


def _lower(parts, pre):
    return (">=", _complete(parts) + (pre,))


def _parse_comparator(tok: str):
    op, rest = _OP_RE.fullmatch(tok).groups()
    parts, pre = _parse_partial(rest)
    n = len(parts)
    if op in (">", ">=", "<", "<="):
        if n != 3:
            raise RangeError(f"operator requires full version: {tok!r}")
        return [(op, (*parts, pre))]
    if op == "^":
        if n == 0:
            raise RangeError("caret requires a major component")
        idx = next((i for i, p in enumerate(parts) if p != 0), n - 1)
        return [_lower(parts, pre), ("<", _bump(parts, idx))]
    if op == "~":
        if n == 0:
            raise RangeError("tilde requires a major component")
        idx = 1 if n >= 2 else 0
        return [_lower(parts, pre), ("<", _bump(parts, idx))]
    if n == 0:
        return [(">=", (0, 0, 0, None))]
    if n == 3:
        return [("=", (*parts, pre))]
    return [_lower(parts, None), ("<", _bump(parts, n - 1))]


def _parse_set(tokens):
    if "-" in tokens:
        if len(tokens) != 3 or tokens[1] != "-":
            raise RangeError("malformed hyphen range")
        a_parts, a_pre = _parse_partial(tokens[0])
        b_parts, b_pre = _parse_partial(tokens[2])
        if not a_parts or not b_parts:
            raise RangeError("hyphen range bounds need a major component")
        out = [_lower(a_parts, a_pre)]
        if len(b_parts) == 3:
            out.append(("<=", (*b_parts, b_pre)))
        else:
            out.append(("<", _bump(b_parts, len(b_parts) - 1)))
        return out
    prims = []
    for tok in tokens:
        prims.extend(_parse_comparator(tok))
    return prims


def _parse_range(expr: str):
    if not expr.strip():
        return [[(">=", (0, 0, 0, None))]]
    sets = []
    for side in expr.split("||"):
        tokens = side.split()
        if not tokens:
            raise RangeError("empty comparator set")
        sets.append(_parse_set(tokens))
    return sets


def _holds(op, a, b):
    if op == "=":
        return a == b
    if op == ">":
        return a > b
    if op == ">=":
        return a >= b
    if op == "<":
        return a < b
    return a <= b


def _satisfies(v, prims):
    k = _key(v)
    for op, pv in prims:
        if not _holds(op, k, _key(pv)):
            return False
    if v[3] is None:
        return True
    return any(pv[3] is not None and pv[:3] == v[:3] for _, pv in prims)


def max_satisfying(versions: list[str], range_expr: str) -> str | None:
    """Return the highest version in `versions` that satisfies `range_expr`."""
    parsed = [_parse_version(s) for s in versions]
    sets = _parse_range(range_expr)
    best = None
    best_key = None
    for s, v in zip(versions, parsed):
        if not any(_satisfies(v, prims) for prims in sets):
            continue
        k = _key(v)
        if best_key is None or k > best_key:
            best, best_key = s, k
    return best
